class DummyServer(object):
    def __init__(self):
        """Dummy server"""
        self.running = False
        self.log_path = None

    def start(self):
        """Dummy start"""
        self.running = True

    def stop(self):
        """Dummy stop"""
        self.running = False

    def is_running(self):
        """Dummy is_running"""
        return self.running

    def get_statistics(self):
        """Dummy get_statistics"""
        return "Dummy class, just to keep consistency while running Ping"

    def reset_statistics(self):
        """Dummy reset_statistics"""
        return "Dummy class, just to keep consistency while running Ping"
